import numpy as np

def norm(v):
    v=np.array(v,float); return v/np.linalg.norm(v)
def perp_basis(v):
    v=norm(v)
    a=np.array([1.0,0,0]) if abs(v[0])<0.9 else np.array([0,1.0,0])
    e1=norm(np.cross(v,a)); e2=norm(np.cross(v,e1)); return e1,e2
def complete_tetra(existing):
    n=len(existing); ct,st=-1/3,np.sqrt(8/9)
    if n==1:
        v1=norm(existing[0]); e1,e2=perp_basis(v1); out=[]
        for k in range(3):
            ang=2*np.pi*k/3
            out.append(norm(ct*v1+st*(np.cos(ang)*e1+np.sin(ang)*e2)))
        return out
    elif n==2:
        v1,v2=norm(existing[0]),norm(existing[1]); mid=-(v1+v2)/2
        t=np.cross(v1,v2); nt=np.linalg.norm(t)
        t = perp_basis(v1)[0] if nt<1e-6 else t/nt
        t=t*np.sqrt(2/3)
        return [norm(mid+t),norm(mid-t)]
    else:
        return [norm(-sum(norm(e) for e in existing))]

Nb_p=np.array([0,0,0.]); Cl_p=np.array([0,0,2.35])
N1_p=np.array([-0.72,-0.10,-1.95]); N2_p=np.array([0.72,-0.10,-1.95])
P1_p=np.array([-2.65,0.0,-0.30]); P2_p=np.array([2.65,0.0,-0.30])

def si_circle(Np,Pp,rNSi=1.80,rPSi=3.15):
    d=np.linalg.norm(Pp-Np); axis=norm(Pp-Np)
    a=(rNSi**2-rPSi**2+d**2)/(2*d); h=np.sqrt(max(rNSi*rNSi-a*a,1e-6))
    M=Np+a*axis; e1,e2=perp_basis(axis); return M,h,e1,e2
M1,h1,e1a,e2a=si_circle(N1_p,P1_p); M2,h2,e1b,e2b=si_circle(N2_p,P2_p)

def place_bridge(Ppos,Sipos,side,r=1.87):
    d=np.linalg.norm(Sipos-Ppos); axis=norm(Sipos-Ppos)
    a=d/2; h=np.sqrt(max(r*r-a*a,0.01)); M=Ppos+a*axis
    fwd=norm(np.array([side*0.7,1.0,-0.2])); fp=fwd-np.dot(fwd,axis)*axis
    if np.linalg.norm(fp)<1e-6: fp=perp_basis(axis)[0]
    return M+h*norm(fp)

best=None
for deg1 in range(0,360,10):
    S1=M1+h1*(np.cos(np.radians(deg1))*e1a+np.sin(np.radians(deg1))*e2a)
    C1p=place_bridge(P1_p,S1,-1)
    md1=complete_tetra([norm(N1_p-S1),norm(C1p-S1)])
    mcs1=[S1+d*1.88 for d in md1]
    for deg2 in range(0,360,10):
        S2=M2+h2*(np.cos(np.radians(deg2))*e1b+np.sin(np.radians(deg2))*e2b)
        if np.linalg.norm(S1-S2)<2.5: continue
        C2p=place_bridge(P2_p,S2,+1)
        md2=complete_tetra([norm(N2_p-S2),norm(C2p-S2)])
        mcs2=[S2+d*1.88 for d in md2]
        allmc=mcs1+mcs2; mind=1e9
        for i in range(4):
            for j in range(i+1,4):
                dd=np.linalg.norm(allmc[i]-allmc[j]); mind=min(mind,dd)
        # want Si forward(+y) and down(-z): reward
        score=mind + 0.05*(S1[1]+S2[1]) - 0.05*(S1[2]+S2[2])
        if best is None or score>best[0]:
            best=(score,mind,deg1,deg2,S1,S2,C1p,C2p)
print("best:",best[2],best[3],"minMe:",round(best[1],3))
_,_,deg1,deg2,S1,S2,C1p,C2p=best

atoms=[]
def add(el,xyz): atoms.append((el,np.array(xyz,float))); return len(atoms)-1
pos=lambda i: atoms[i][1]
Nb=add('Nb',Nb_p); Cl=add('Cl',Cl_p)
N1=add('N',N1_p); N2=add('N',N2_p); P1=add('P',P1_p); P2=add('P',P2_p)
Si1=add('Si',S1); Si2=add('Si',S2); C1=add('C',C1p); C2=add('C',C2p)

def place_P_subs(Pidx, Cidx):
    dNb=norm(pos(Nb)-pos(Pidx)); dC=norm(pos(Cidx)-pos(Pidx))
    d1,d2=complete_tetra([dNb,dC])
    return (d1,d2) if d1[2]>d2[2] else (d2,d1)
sid1,phd1=place_P_subs(P1,C1); sid2,phd2=place_P_subs(P2,C2)
Si3=add('Si',pos(P1)+sid1*2.30); Si4=add('Si',pos(P2)+sid2*2.30)

def add_phenyl(Ppos,v,u):
    v=norm(v); Cip=Ppos+v*1.85; r=1.40; O=Cip+v*r; ring=[]
    ring.append(add('C',O+r*(-v)))
    for ang in (120,60,0,-60,-120):
        a=np.radians(ang); dirv=np.cos(a)*v+np.sin(a)*u
        ring.append(add('C',O+r*dirv))
    for k,idx in enumerate(ring[1:]):
        Cp=atoms[idx][1]; a=np.radians([120,60,0,-60,-120][k])
        dirv=np.cos(a)*v+np.sin(a)*u
        add('H',Cp+dirv*1.09)
    return ring
def phenyl_u(v):
    e1,e2=perp_basis(v); return e1 if abs(e1[1])<abs(e2[1]) else e2
Ph1=add_phenyl(pos(P1),phd1,phenyl_u(phd1)); Ph2=add_phenyl(pos(P2),phd2,phenyl_u(phd2))

def add_methyl(SiIdx, existing_dirs, n_new):
    Spos=pos(SiIdx); out=[]
    for d in complete_tetra(existing_dirs)[:n_new]: out.append(add('C',Spos+d*1.88))
    return out
mSi1=add_methyl(Si1,[pos(N1)-pos(Si1),pos(C1)-pos(Si1)],2)
mSi2=add_methyl(Si2,[pos(N2)-pos(Si2),pos(C2)-pos(Si2)],2)
mSi3=add_methyl(Si3,[pos(P1)-pos(Si3)],3)
mSi4=add_methyl(Si4,[pos(P2)-pos(Si4)],3)

def add_CH2(Cidx,d1,d2):
    for d in complete_tetra([d1,d2]): add('H',pos(Cidx)+d*1.09)
add_CH2(C1,pos(Si1)-pos(C1),pos(P1)-pos(C1))
add_CH2(C2,pos(Si2)-pos(C2),pos(P2)-pos(C2))
def add_CH3(Cidx,toSi):
    for d in complete_tetra([toSi]): add('H',pos(Cidx)+d*1.09)
for grp,si in [(mSi1,Si1),(mSi2,Si2),(mSi3,Si3),(mSi4,Si4)]:
    for c in grp: add_CH3(c,pos(si)-pos(c))

with open('initial.xyz','w') as f:
    f.write(f"{len(atoms)}\ninit\n")
    for el,p in atoms: f.write(f"{el:2s} {p[0]:12.6f} {p[1]:12.6f} {p[2]:12.6f}\n")

n=len(atoms); worst=[]
for i in range(n):
    for j in range(i+1,n):
        dd=np.linalg.norm(pos(i)-pos(j))
        if dd<0.95: worst.append((i,atoms[i][0],j,atoms[j][0],round(dd,3)))
print("atoms:",n," clashes<0.95:",len(worst))
for w in worst: print("  ",w)
def d(i,j): return np.linalg.norm(pos(i)-pos(j))
for lbl,i,j in [("N1-N2",N1,N2),("Nb-N1",Nb,N1),("P1-Si1",P1,Si1),("P2-Si2",P2,Si2),
                ("Si1-Si2",Si1,Si2),("N1-Si1",N1,Si1),("Si1-C1",Si1,C1),("P1-C1",P1,C1)]:
    print(lbl,round(d(i,j),3))
